from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)

        for i, num in enumerate(nums):
            prefix[i + 1] = prefix[i] + num

        NEG = float("-inf")
        dp = [[NEG] * (k + 1) for _ in range(n + 1)]

        for i in range(n + 1):
            dp[i][0] = 0

        for j in range(1, k + 1):
            best = NEG

            for i in range(1, n + 1):
                start = i - m

                if start >= 0:
                    best = max(best, dp[start][j - 1] - prefix[start])

                dp[i][j] = dp[i - 1][j]

                if best != NEG:
                    dp[i][j] = max(dp[i][j], best + prefix[i])

        return dp[n][k]
